data.query:
query Inventory($whereInventory: InventoryWhereInput!, $whereStorageUnit: StorageUnitWhereInput!) {
  inventory: inventory(where: $whereInventory) {
    edges {
      node {
        id
        serialNumber
        active
        handlingUnitId
        inventoryStatusId
        productId
        product{ code }
        storageUnitId
        storageUnit {
          active
          code
          storageUnitStatusId
          storageUnitStatus {
            active
            code
          }
        }
      }
    }
  }

  storageUnit: storageUnit(where: $whereStorageUnit) {
    edges {
      node {
        id
        code
        defaultInventoryStatusId
        defaultInventoryStatus {
          code
        }
        storageUnitStatusId
        storageUnitStatus {
          active
          code
        }
        inventories{
          total
          edges{
            node{
              product{id code }
              _aggregate{
                id{
                  uniqueValues
                }
              }
            }
          }
        }
      }
    }
  }
}

data.mutation:
mutation UpdateInventory($payload: [InventoryUpdatePayloadInput!]!) {
  updateInventory(payload: $payload) {
    id
    handlingUnitId
    inventoryStatusId
    lastTransactionTypeId
    storageUnitId
  }
}

data.responseTransform:
{
  "success": true,
  "severity": "success",
  "message": "Inventory moved successfully",
  "data": {
    "Moved Inventory": $state.context.INFO.inventory.{
      "ID": id,
      "Serial Number": serialNumber,
      "Previous Storage Unit": storageUnit.code,
      "Removed From Handling Unit ID": $state.context.INPUT.removeFromHandlingUnit ? $coalesce([handlingUnitId, "N/A"])
    },
    "New Storage Unit": $state.context.INPUT.storageUnit.code
  }
}

{
  "success": true,
  "severity": "info",
  "title": "Inventory Already At Storage Unit",
  "message": "All inventory is already at the storage unit",
  "data": {
    "Storage Unit": $state.context.INFO.storageUnit.code,
    "Inventory Serial Numbers": [$state.context.INFO.inventory.serialNumber]
  }
}

{
  "success": false,
  "severity": "error",
  "title": "Storage Unit Not Active",
  "message": "This storage unit has been \"soft deleted\", meaning it exists only as an archive and cannot be used. If you believe this is incorrect, contact your supervisor or Fuuz admin for help.",
  "data": {
    "Storage Unit": $state.context.INFO.storageUnit.code,
    "Storage Unit ID": $state.context.INPUT.storageUnitId
  }
}

{
  "success": false,
  "severity": "error",
  "title": "Inventory is Inactive",
  "message": "Some or all of the selected inventory is inactive, which means it was \"soft deleted\" and only exists as an archive. It cannot be used. If you believe this is incorrect, contact your supervisor or Fuuz admin to fix it.",
  "data": {
    "Inactive Inventory IDs": [
      $state.context.INFO.inventory@$active.active.id
    ][$active = false]
  }
}

{
  "success": false,
  "severity": "error",
  "title": "Invalid Status Found",
  "message": "The status of the storage unit is invalid and can no longer be used. Edit the status of the storage unit to fix this issue.",
  "data": {
    "Storage Unit": $state.context.INFO.storageUnit.code,
    "Storage Unit ID": $state.context.INPUT.storageUnitId,
    "Storage Unit Status Code": $state.context.INFO.storageUnit.storageUnitStatus.code
  }
}

{
  "success": false,
  "severity": "error",
  "title": "Inventory is Retired",
  "message": "Some or all of the selected inventory is retired, which means it has completed its journey and now exists as a historical record.",
  "data": {
    "Inactive Inventory IDs": [
      $state.context.INFO.inventory@$active.active.id
    ][$active = false]
  }
}

{
  "success": false,
  "severity": "error",
  "title": "Incorrect Product",
  "message": "The storage unit is already filled with another product.",
  "data": {
    "Storage Unit": $state.context.INFO.storageUnit.code,
    "Storage Unit ID": $state.context.INPUT.storageUnitId,
    "Storage Unit Status Code": $state.context.INFO.storageUnit.storageUnitStatus.code
  }
}

